import socket
import selectors
import threading
import types
import sys

class ChatServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 0):
        self.host = host
        self.port = port
        self._sel = selectors.DefaultSelector()
        self._sock = None
        self._thread = None
        self._running = False
        self._lock = threading.Lock()
        self._clients = {}  # name -> (conn, addr)
        self._conn_to_name = {}  # conn -> name

    def start(self) -> int:
        if self._running:
            return self.port
        self._sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._sock.bind((self.host, self.port))
        self._sock.listen()
        self._sock.setblocking(False)
        self.port = self._sock.getsockname()[1]
        self._sel.register(self._sock, selectors.EVENT_READ, data=None)
        self._running = True
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()
        return self.port

    def stop(self):
        if not self._running:
            return
        self._running = False
        self._sel.close()
        try:
            self._sock.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        self._sock.close()
        self._thread.join()

    def _run(self):
        while self._running:
            events = self._sel.select(timeout=1)
            for key, mask in events:
                if key.data is None:
                    self._accept(key.fileobj)
                else:
                    self._service_connection(key, mask)

    def _accept(self, sock):
        conn, addr = sock.accept()
        conn.setblocking(False)
        data = types.SimpleNamespace(addr=addr, inb=b"", outb=b"", name=None)
        self._sel.register(conn, selectors.EVENT_READ, data=data)

    def _service_connection(self, key, mask):
        sock = key.fileobj
        data = key.data
        try:
            if mask & selectors.EVENT_READ:
                recv_data = sock.recv(4096)
                if recv_data:
                    data.inb += recv_data
                    while b'\n' in data.inb:
                        line, data.inb = data.inb.split(b'\n', 1)
                        self._handle_line(sock, data, line.decode('utf-8', errors='ignore'))
                else:
                    self._disconnect(sock, data)
            if mask & selectors.EVENT_WRITE and data.outb:
                sent = sock.send(data.outb)
                data.outb = data.outb[sent:]
                if not data.outb:
                    self._sel.modify(sock, selectors.EVENT_READ, data=data)
        except ConnectionResetError:
            self._disconnect(sock, data)

    def _handle_line(self, sock, data, line):
        if data.name is None:
            if not line.startswith("NAME "):
                self._send_and_close(sock, "ERROR bad name\n")
                return
            name = line[5:].strip()
            with self._lock:
                if name in self._clients:
                    self._send_and_close(sock, "ERROR name taken\n")
                    return
                data.name = name
                self._clients[name] = (sock, data.addr)
                self._conn_to_name[sock] = name
            self._send(sock, "OK\n")
            self._broadcast(f"* {name} joined\n", exclude=sock)
        else:
            msg = f"{data.name}: {line}\n"
            self._broadcast(msg, exclude=sock)

    def _broadcast(self, msg, exclude=None):
        with self._lock:
            for name, (conn, _) in self._clients.items():
                if conn is exclude:
                    continue
                self._send(conn, msg)

    def _send(self, sock, msg):
        data = self._sel.get_key(sock).data
        data.outb += msg.encode('utf-8')
        self._sel.modify(sock, selectors.EVENT_READ | selectors.EVENT_WRITE, data=data)

    def _send_and_close(self, sock, msg):
        try:
            sock.sendall(msg.encode('utf-8'))
        except OSError:
            pass
        self._disconnect(sock, self._sel.get_key(sock).data)

    def _disconnect(self, sock, data):
        name = data.name
        if name:
            with self._lock:
                self._clients.pop(name, None)
                self._conn_to_name.pop(sock, None)
            self._broadcast(f"* {name} left\n", exclude=sock)
        try:
            self._sel.unregister(sock)
        except Exception:
            pass
        try:
            sock.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        sock.close()
